/// <reference types="vitest" />
import { defineConfig } from "vite";
import react from "@vitejs/plugin-react";

export default defineConfig({
  plugins: [react()],
  test: { environment: "node" },
});

import { StrictMode } from "react";
import { createRoot } from "react-dom/client";
import App from "./App";
import "./styles.css";

createRoot(document.getElementById("root")!).render(
  <StrictMode>
    <App />
  </StrictMode>,
);

export default function App() {
  return <h1>Virtual Office</h1>;
}

export const EMPLOYEE_IDS = ["planner", "developer", "qa", "security", "researcher"] as const;
export type EmployeeId = (typeof EMPLOYEE_IDS)[number];

export type EmployeeState = "idle" | "working" | "thinking" | "waiting" | "completed" | "error";
export type TaskStatus = "todo" | "active" | "done";

export interface Task {
  id: string;
  title: string;
  assigneeId: EmployeeId | null;
  status: TaskStatus;
  createdAt: number;
  updatedAt: number;
}

export interface LogEntry {
  at: number;
  employeeId: EmployeeId | null;
  text: string;
}

export interface Employee {
  id: EmployeeId;
  role: string;
  state: EmployeeState;
  currentTaskId: string | null;
  activity: LogEntry[];
}

export interface Settings {
  theme: "day" | "night";
  sound: boolean;
}

export interface OfficeState {
  employees: Record<EmployeeId, Employee>;
  tasks: Task[];
  log: LogEntry[];
  settings: Settings;
  error: string | null;
}

export type Action = { at: number } & (
  | { type: "createTask"; id: string; title: string; assigneeId?: EmployeeId }
  | { type: "assignTask"; taskId: string; assigneeId: EmployeeId }
  | { type: "startTask"; taskId: string }
  | { type: "completeTask"; taskId: string }
  | { type: "setState"; employeeId: EmployeeId; state: EmployeeState }
  | { type: "settleCompleted"; employeeId: EmployeeId }
  | { type: "setTheme"; theme: Settings["theme"] }
  | { type: "setSound"; sound: boolean }
  | { type: "clearLog" }
  | { type: "dismissError" }
);

import { describe, expect, it } from "vitest";
import { initialState, reduce } from "./reducer";
import type { Action, EmployeeId, OfficeState } from "./types";

type Body = Action extends infer A ? (A extends { at: number } ? Omit<A, "at"> : never) : never;

let clock = 1000;
const step = (s: OfficeState, a: Body): OfficeState => reduce(s, { ...a, at: ++clock } as Action);

const withTask = (s: OfficeState, id: string, assigneeId?: EmployeeId) =>
  step(s, { type: "createTask", id, title: `Task ${id}`, assigneeId });

describe("reducer", () => {
  it("createTask rejects empty and whitespace titles", () => {
    for (const title of ["", "   "]) {
      const s = step(initialState(), { type: "createTask", id: "t1", title });
      expect(s.tasks.length).toBe(0);
      expect(s.error).not.toBeNull();
    }
  });

  it("createTask trims title", () => {
    const s = step(initialState(), { type: "createTask", id: "t1", title: "  Draft plan  " });
    expect(s.tasks[0].title).toBe("Draft plan");
    expect(s.tasks[0].status).toBe("todo");
  });

  it("start then complete moves employee idle->working->completed and task todo->active->done", () => {
    let s = withTask(initialState(), "t1", "developer");
    expect(s.employees.developer.state).toBe("idle");
    s = step(s, { type: "startTask", taskId: "t1" });
    expect(s.employees.developer.state).toBe("working");
    expect(s.employees.developer.currentTaskId).toBe("t1");
    expect(s.tasks[0].status).toBe("active");
    s = step(s, { type: "completeTask", taskId: "t1" });
    expect(s.employees.developer.state).toBe("completed");
    expect(s.employees.developer.currentTaskId).toBeNull();
    expect(s.tasks[0].status).toBe("done");
  });

  it("startTask twice on same task is rejected", () => {
    let s = withTask(initialState(), "t1", "qa");
    s = step(s, { type: "startTask", taskId: "t1" });
    const logLen = s.log.length;
    const again = step(s, { type: "startTask", taskId: "t1" });
    expect(again.error).not.toBeNull();
    expect(again.log.length).toBe(logLen);
  });

  it("startTask on busy employee is rejected", () => {
    let s = withTask(initialState(), "t1", "developer");
    s = withTask(s, "t2", "developer");
    s = step(s, { type: "startTask", taskId: "t1" });
    s = step(s, { type: "startTask", taskId: "t2" });
    expect(s.error).not.toBeNull();
    expect(s.tasks.find((t) => t.id === "t2")!.status).toBe("todo");
  });

  it("startTask without assignee is rejected", () => {
    let s = withTask(initialState(), "t1");
    s = step(s, { type: "startTask", taskId: "t1" });
    expect(s.error).not.toBeNull();
    expect(s.tasks[0].status).toBe("todo");
  });

  it("setState working without task is rejected", () => {
    const s = step(initialState(), { type: "setState", employeeId: "planner", state: "working" });
    expect(s.error).not.toBeNull();
    expect(s.employees.planner.state).toBe("idle");
  });

  it("setState accepts thinking, waiting and error", () => {
    let s = initialState();
    for (const state of ["thinking", "waiting", "error"] as const) {
      s = step(s, { type: "setState", employeeId: "security", state });
      expect(s.employees.security.state).toBe(state);
    }
  });

  it("settleCompleted only affects completed employees", () => {
    let s = step(initialState(), { type: "setState", employeeId: "qa", state: "error" });
    s = step(s, { type: "settleCompleted", employeeId: "qa" });
    expect(s.employees.qa.state).toBe("error");
    let d = withTask(initialState(), "t1", "developer");
    d = step(d, { type: "startTask", taskId: "t1" });
    d = step(d, { type: "completeTask", taskId: "t1" });
    d = step(d, { type: "settleCompleted", employeeId: "developer" });
    expect(d.employees.developer.state).toBe("idle");
  });

  it("employee activity caps at 20 and global log at 50", () => {
    let s = initialState();
    for (let i = 0; i < 60; i++) {
      s = step(s, { type: "setState", employeeId: "planner", state: i % 2 ? "thinking" : "waiting" });
    }
    expect(s.employees.planner.activity.length).toBe(20);
    expect(s.log.length).toBe(50);
  });

  it("dismissError clears error", () => {
    let s = step(initialState(), { type: "createTask", id: "t1", title: "" });
    expect(s.error).not.toBeNull();
    s = step(s, { type: "dismissError" });
    expect(s.error).toBeNull();
  });
});

import { EMPLOYEE_IDS } from "./types";
import type { Action, Employee, EmployeeId, OfficeState, Task } from "./types";

const LOG_CAP = 50;
const ACTIVITY_CAP = 20;

export const ROLES: Record<EmployeeId, string> = {
  planner: "Planner / Architect",
  developer: "Developer",
  qa: "QA / Debugger",
  security: "Security Auditor",
  researcher: "Researcher / Codebase Explorer",
};

export function initialEmployees(): Record<EmployeeId, Employee> {
  const out = {} as Record<EmployeeId, Employee>;
  for (const id of EMPLOYEE_IDS) {
    out[id] = { id, role: ROLES[id], state: "idle", currentTaskId: null, activity: [] };
  }
  return out;
}

export function initialState(): OfficeState {
  return {
    employees: initialEmployees(),
    tasks: [],
    log: [],
    settings: { theme: "day", sound: false },
    error: null,
  };
}

const reject = (s: OfficeState, message: string): OfficeState => ({ ...s, error: message });

function logged(s: OfficeState, at: number, employeeId: EmployeeId | null, text: string): OfficeState {
  const entry = { at, employeeId, text };
  const employees = employeeId
    ? {
        ...s.employees,
        [employeeId]: {
          ...s.employees[employeeId],
          activity: [...s.employees[employeeId].activity, entry].slice(-ACTIVITY_CAP),
        },
      }
    : s.employees;
  return { ...s, employees, log: [...s.log, entry].slice(-LOG_CAP), error: null };
}

const patchTask = (s: OfficeState, id: string, patch: Partial<Task>): OfficeState => ({
  ...s,
  tasks: s.tasks.map((t) => (t.id === id ? { ...t, ...patch } : t)),
});

const patchEmployee = (s: OfficeState, id: EmployeeId, patch: Partial<Employee>): OfficeState => ({
  ...s,
  employees: { ...s.employees, [id]: { ...s.employees[id], ...patch } },
});

export function reduce(s: OfficeState, a: Action): OfficeState {
  switch (a.type) {
    case "createTask": {
      const title = a.title.trim();
      if (!title) return reject(s, "Task title is empty.");
      const task: Task = {
        id: a.id,
        title,
        assigneeId: a.assigneeId ?? null,
        status: "todo",
        createdAt: a.at,
        updatedAt: a.at,
      };
      return logged({ ...s, tasks: [...s.tasks, task] }, a.at, task.assigneeId, `Task created: ${title}`);
    }
    case "assignTask": {
      const task = s.tasks.find((t) => t.id === a.taskId);
      if (!task) return reject(s, "Task not found.");
      if (task.status !== "todo") return reject(s, "Only to-do tasks can be assigned.");
      return logged(
        patchTask(s, task.id, { assigneeId: a.assigneeId, updatedAt: a.at }),
        a.at,
        a.assigneeId,
        `Assigned: ${task.title}`,
      );
    }
    case "startTask": {
      const task = s.tasks.find((t) => t.id === a.taskId);
      if (!task) return reject(s, "Task not found.");
      if (task.status !== "todo") return reject(s, "Task was already started or finished.");
      if (!task.assigneeId) return reject(s, "Assign the task to someone first.");
      const emp = s.employees[task.assigneeId];
      if (emp.currentTaskId !== null) return reject(s, `${emp.role} is busy with another task.`);
      const next = patchEmployee(patchTask(s, task.id, { status: "active", updatedAt: a.at }), emp.id, {
        state: "working",
        currentTaskId: task.id,
      });
      return logged(next, a.at, emp.id, `Started: ${task.title}`);
    }
    case "completeTask": {
      const task = s.tasks.find((t) => t.id === a.taskId);
      if (!task) return reject(s, "Task not found.");
      if (task.status !== "active" || !task.assigneeId) return reject(s, "Only active tasks can be completed.");
      const next = patchEmployee(patchTask(s, task.id, { status: "done", updatedAt: a.at }), task.assigneeId, {
        state: "completed",
        currentTaskId: null,
      });
      return logged(next, a.at, task.assigneeId, `Completed: ${task.title}`);
    }
    case "setState": {
      const emp = s.employees[a.employeeId];
      if (a.state === "working" && !emp.currentTaskId) return reject(s, "Start a task to make someone work.");
      return logged(patchEmployee(s, emp.id, { state: a.state }), a.at, emp.id, `State set to ${a.state}`);
    }
    case "settleCompleted": {
      if (s.employees[a.employeeId].state !== "completed") return s;
      return patchEmployee(s, a.employeeId, { state: "idle" });
    }
    case "setTheme":
      return { ...s, settings: { ...s.settings, theme: a.theme } };
    case "setSound":
      return { ...s, settings: { ...s.settings, sound: a.sound } };
    case "clearLog":
      return { ...s, log: [] };
    case "dismissError":
      return { ...s, error: null };
  }
}

import { describe, expect, it } from "vitest";
import { STORAGE_KEY, loadState, saveState } from "./persistence";
import { initialState, reduce } from "./reducer";
import type { Action, OfficeState } from "./types";

const fake = (value: string | null = null) => {
  const m = new Map<string, string>();
  if (value !== null) m.set(STORAGE_KEY, value);
  return {
    getItem: (k: string) => m.get(k) ?? null,
    setItem: (k: string, v: string) => void m.set(k, v),
  };
};

const act = (s: OfficeState, a: Omit<Action, "at"> & Record<string, unknown>): OfficeState =>
  reduce(s, { ...a, at: 1 } as Action);

describe("persistence", () => {
  it("missing value returns initial state", () => {
    expect(loadState(fake())).toEqual(initialState());
  });

  it("invalid JSON returns initial state", () => {
    expect(loadState(fake("{not json"))).toEqual(initialState());
  });

  it("wrong version returns initial state", () => {
    expect(loadState(fake(JSON.stringify({ version: 99, tasks: [{}] })))).toEqual(initialState());
  });

  it("getItem throwing returns initial state", () => {
    const boom = {
      getItem: () => {
        throw new Error("denied");
      },
    };
    expect(loadState(boom)).toEqual(initialState());
  });

  it("saveState swallows setItem errors", () => {
    const boom = {
      setItem: () => {
        throw new Error("quota");
      },
    };
    expect(() => saveState(initialState(), boom)).not.toThrow();
  });

  it("round trip keeps tasks, settings and employee states", () => {
    let s = act(initialState(), { type: "createTask", id: "t1", title: "Build", assigneeId: "developer" });
    s = act(s, { type: "startTask", taskId: "t1" });
    s = act(s, { type: "setTheme", theme: "night" });
    s = act(s, { type: "setSound", sound: true });
    s = act(s, { type: "setState", employeeId: "qa", state: "error" });
    const storage = fake();
    saveState(s, storage);
    const loaded = loadState(storage);
    expect(loaded.tasks).toEqual(s.tasks);
    expect(loaded.settings).toEqual({ theme: "night", sound: true });
    expect(loaded.employees.developer.state).toBe("working");
    expect(loaded.employees.developer.currentTaskId).toBe("t1");
    expect(loaded.employees.qa.state).toBe("error");
    expect(loaded.log).toEqual(s.log);
  });

  it("working employee with missing task is repaired to idle", () => {
    let s = act(initialState(), { type: "createTask", id: "t1", title: "Build", assigneeId: "developer" });
    s = act(s, { type: "startTask", taskId: "t1" });
    const storage = fake();
    saveState({ ...s, tasks: [] }, storage);
    const loaded = loadState(storage);
    expect(loaded.employees.developer.state).toBe("idle");
    expect(loaded.employees.developer.currentTaskId).toBeNull();
  });

  it("completed employee loads as idle", () => {
    let s = act(initialState(), { type: "createTask", id: "t1", title: "Build", assigneeId: "developer" });
    s = act(s, { type: "startTask", taskId: "t1" });
    s = act(s, { type: "completeTask", taskId: "t1" });
    const storage = fake();
    saveState(s, storage);
    expect(loadState(storage).employees.developer.state).toBe("idle");
  });
});

import { initialState } from "./reducer";
import { EMPLOYEE_IDS } from "./types";
import type { EmployeeState, LogEntry, OfficeState, Task } from "./types";

export const STORAGE_KEY = "virtual-office:v1";
const VERSION = 1;
const STATES: EmployeeState[] = ["idle", "working", "thinking", "waiting", "completed", "error"];

type Rec = Record<string, unknown>;
const isRec = (v: unknown): v is Rec => typeof v === "object" && v !== null && !Array.isArray(v);

const isEntry = (v: unknown): v is LogEntry =>
  isRec(v) && typeof v.at === "number" && typeof v.text === "string" &&
  (v.employeeId === null || (EMPLOYEE_IDS as readonly unknown[]).includes(v.employeeId));

const isTask = (v: unknown): v is Task =>
  isRec(v) && typeof v.id === "string" && typeof v.title === "string" &&
  typeof v.createdAt === "number" && typeof v.updatedAt === "number" &&
  (v.status === "todo" || v.status === "active" || v.status === "done") &&
  (v.assigneeId === null || (EMPLOYEE_IDS as readonly unknown[]).includes(v.assigneeId));

export function saveState(state: OfficeState, storage: Pick<Storage, "setItem"> = globalThis.localStorage): void {
  try {
    const employees = Object.fromEntries(
      EMPLOYEE_IDS.map((id) => {
        const { state: st, currentTaskId, activity } = state.employees[id];
        return [id, { state: st, currentTaskId, activity }];
      }),
    );
    storage.setItem(
      STORAGE_KEY,
      JSON.stringify({ version: VERSION, tasks: state.tasks, employees, log: state.log, settings: state.settings }),
    );
  } catch {
    // storage unavailable or full: the app keeps running without persistence
  }
}

export function loadState(storage: Pick<Storage, "getItem"> = globalThis.localStorage): OfficeState {
  const base = initialState();
  try {
    const raw = storage.getItem(STORAGE_KEY);
    if (!raw) return base;
    const data: unknown = JSON.parse(raw);
    if (!isRec(data) || data.version !== VERSION) return base;

    const tasks = Array.isArray(data.tasks) ? data.tasks.filter(isTask) : [];
    const log = Array.isArray(data.log) ? data.log.filter(isEntry).slice(-50) : [];
    const savedEmps = isRec(data.employees) ? data.employees : {};
    for (const id of EMPLOYEE_IDS) {
      const e = savedEmps[id];
      if (!isRec(e)) continue;
      const taskId = typeof e.currentTaskId === "string" ? e.currentTaskId : null;
      let state = STATES.includes(e.state as EmployeeState) ? (e.state as EmployeeState) : "idle";
      let currentTaskId = taskId;
      const active = tasks.some((t) => t.id === taskId && t.status === "active");
      if (state === "completed") state = "idle";
      if (state === "working" && !active) state = "idle";
      if (!active) currentTaskId = null;
      base.employees[id] = {
        ...base.employees[id],
        state,
        currentTaskId,
        activity: Array.isArray(e.activity) ? e.activity.filter(isEntry).slice(-20) : [],
      };
    }
    const s = isRec(data.settings) ? data.settings : {};
    base.settings = {
      theme: s.theme === "night" ? "night" : "day",
      sound: s.sound === true,
    };
    return { ...base, tasks, log };
  } catch {
    return initialState();
  }
}

import { describe, expect, it } from "vitest";
import { COLS, OBJECTS, ROWS, SEATS } from "./layout";
import type { SceneObject } from "./layout";
import { EMPLOYEE_IDS } from "../state/types";

const overlap = (a: { x: number; y: number; w: number; h: number }, b: { x: number; y: number; w: number; h: number }) =>
  a.x < b.x + b.w && b.x < a.x + a.w && a.y < b.y + b.h && b.y < a.y + a.h;
const solids = (): SceneObject[] => OBJECTS.filter((o) => o.solid);

describe("layout", () => {
  it("all objects lie inside the grid", () => {
    for (const o of OBJECTS) {
      expect(o.x, o.id).toBeGreaterThanOrEqual(0);
      expect(o.y, o.id).toBeGreaterThanOrEqual(0);
      expect(o.x + o.w, o.id).toBeLessThanOrEqual(COLS);
      expect(o.y + o.h, o.id).toBeLessThanOrEqual(ROWS);
    }
  });

  it("no two solid objects overlap", () => {
    const s = solids();
    for (let i = 0; i < s.length; i++) {
      for (let j = i + 1; j < s.length; j++) {
        expect(overlap(s[i], s[j]), `${s[i].id} vs ${s[j].id}`).toBe(false);
      }
    }
  });

  it("every seat is inside the grid and not on a solid object", () => {
    for (const id of EMPLOYEE_IDS) {
      const p = SEATS[id];
      expect(p.x).toBeGreaterThanOrEqual(0);
      expect(p.y).toBeGreaterThanOrEqual(0);
      expect(p.x).toBeLessThan(COLS);
      expect(p.y).toBeLessThan(ROWS);
      for (const o of solids()) {
        expect(overlap({ x: p.x, y: p.y, w: 1, h: 1 }, o), `${id} on ${o.id}`).toBe(false);
      }
    }
  });

  it("each employee id has exactly one seat and seats are distinct", () => {
    expect(Object.keys(SEATS).sort()).toEqual([...EMPLOYEE_IDS].sort());
    const keys = new Set(EMPLOYEE_IDS.map((id) => `${SEATS[id].x},${SEATS[id].y}`));
    expect(keys.size).toBe(EMPLOYEE_IDS.length);
  });

  it("layout contains one desk per role plus meeting table, whiteboard, task board and server rack", () => {
    const desks = OBJECTS.filter((o) => o.kind === "desk").map((o) => o.id).sort();
    expect(desks).toEqual(EMPLOYEE_IDS.map((id) => `desk-${id}`).sort());
    for (const kind of ["meetingTable", "whiteboard", "taskBoard", "serverRack"] as const) {
      expect(OBJECTS.filter((o) => o.kind === kind).length, kind).toBe(1);
    }
  });
});

import type { EmployeeId } from "../state/types";

export const TILE = 16;
export const COLS = 24;
export const ROWS = 14;

export type ObjectKind =
  | "desk" | "computer" | "chair" | "meetingTable" | "whiteboard" | "taskBoard"
  | "serverRack" | "network" | "bookshelf" | "plant" | "window" | "rug";

/** Position and size are in tiles. Non-solid objects are decor that may sit under or on others. */
export interface SceneObject {
  id: string;
  kind: ObjectKind;
  x: number;
  y: number;
  w: number;
  h: number;
  solid: boolean;
}

const o = (id: string, kind: ObjectKind, x: number, y: number, w: number, h: number, solid = true): SceneObject => ({
  id, kind, x, y, w, h, solid,
});

export const SEATS: Record<EmployeeId, { x: number; y: number }> = {
  planner: { x: 2, y: 5 },
  developer: { x: 7, y: 5 },
  qa: { x: 2, y: 10 },
  security: { x: 7, y: 10 },
  researcher: { x: 20, y: 5 },
};

// Desk top-left per employee; the seat sits one tile below the desk's middle.
const DESKS: Record<EmployeeId, { x: number; y: number }> = {
  planner: { x: 1, y: 3 },
  developer: { x: 6, y: 3 },
  qa: { x: 1, y: 8 },
  security: { x: 6, y: 8 },
  researcher: { x: 19, y: 3 },
};

const deskSet = (Object.keys(DESKS) as EmployeeId[]).flatMap((id) => {
  const d = DESKS[id];
  const s = SEATS[id];
  return [
    o(`desk-${id}`, "desk", d.x, d.y, 3, 2),
    o(`computer-${id}`, "computer", s.x, d.y, 1, 1, false),
    o(`chair-${id}`, "chair", s.x, s.y, 1, 1, false),
  ];
});

export const OBJECTS: SceneObject[] = [
  o("rug", "rug", 9, 5, 6, 5, false),
  o("window-1", "window", 2, 0, 2, 1, false),
  o("window-2", "window", 7, 0, 2, 1, false),
  o("window-3", "window", 15, 0, 2, 1, false),
  o("window-4", "window", 20, 0, 2, 1, false),
  o("bookshelf-1", "bookshelf", 4, 0, 2, 2),
  o("bookshelf-2", "bookshelf", 22, 0, 2, 2),
  o("whiteboard", "whiteboard", 10, 0, 4, 2),
  o("task-board", "taskBoard", 17, 0, 2, 2),
  ...deskSet,
  o("meeting-table", "meetingTable", 10, 6, 4, 3),
  o("meeting-chair-1", "chair", 9, 7, 1, 1, false),
  o("meeting-chair-2", "chair", 14, 7, 1, 1, false),
  o("server-rack", "serverRack", 21, 10, 2, 3),
  o("network", "network", 19, 12, 2, 1),
  o("plant-1", "plant", 0, 6, 1, 1),
  o("plant-2", "plant", 23, 7, 1, 1),
  o("plant-3", "plant", 11, 12, 1, 1),
];

import { describe, expect, it } from "vitest";
import { fitScale, hitTestCharacter } from "./hit";
import { SEATS, TILE } from "./layout";
import { labelFor } from "./renderer";
import { EMPLOYEE_IDS } from "../state/types";

describe("hit-testing", () => {
  it("hitTestCharacter returns each employee at its seat", () => {
    for (const id of EMPLOYEE_IDS) {
      const s = SEATS[id];
      expect(hitTestCharacter(s.x * TILE + 8, s.y * TILE + 8)).toBe(id);
    }
  });

  it("hitTestCharacter returns null on empty floor (0,0)", () => {
    expect(hitTestCharacter(0, 0)).toBeNull();
  });

  it("hitTestCharacter returns null on a desk tile away from any character", () => {
    // planner desk top-left tile (1,3)
    expect(hitTestCharacter(1 * TILE + 4, 3 * TILE + 4)).toBeNull();
  });
});

describe("fitScale", () => {
  it("returns integer 3 for 1200x800", () => {
    expect(fitScale(1200, 800)).toBe(3);
  });

  it("returns integer 1 for 400x700 (width bound)", () => {
    expect(fitScale(400, 700)).toBe(1);
  });

  it("returns fractional below 1 for 192x112", () => {
    expect(fitScale(192, 112)).toBe(0.5);
  });
});

describe("labelFor", () => {
  it("truncates long text with ellipsis", () => {
    const out = labelFor("A very long task title", 10);
    expect(out.length).toBe(10);
    expect(out.endsWith("…")).toBe(true);
  });

  it("leaves short and empty text alone", () => {
    expect(labelFor("Short", 10)).toBe("Short");
    expect(labelFor("", 10)).toBe("");
  });
});

import { COLS, ROWS, SEATS, TILE } from "./layout";
import { EMPLOYEE_IDS } from "../state/types";
import type { EmployeeId } from "../state/types";

export const SCENE_W = COLS * TILE;
export const SCENE_H = ROWS * TILE;

/** Character hitbox in logical px, anchored at the seat tile; the head pokes one half-tile above it. */
export const CHAR_BOX = { w: 16, h: 24, dy: -8 };

/** x, y are in logical scene px. Returns null for empty floor and furniture. */
export function hitTestCharacter(x: number, y: number): EmployeeId | null {
  for (const id of EMPLOYEE_IDS) {
    const bx = SEATS[id].x * TILE;
    const by = SEATS[id].y * TILE + CHAR_BOX.dy;
    if (x >= bx && x < bx + CHAR_BOX.w && y >= by && y < by + CHAR_BOX.h) return id;
  }
  return null;
}

/** Integer scale when the scene fits at 1x or larger, otherwise a fractional downscale. */
export function fitScale(containerW: number, containerH: number): number {
  const s = Math.min(containerW / SCENE_W, containerH / SCENE_H);
  return s >= 1 ? Math.floor(s) : s;
}

import type { EmployeeId, EmployeeState } from "../state/types";
import { TILE } from "./layout";
import type { SceneObject } from "./layout";

export type Ctx = CanvasRenderingContext2D;

export const C = {
  ink: "#3b2c22",
  wood: "#b9824f",
  woodDark: "#8a5a34",
  woodLight: "#d5a273",
  cream: "#f4ead2",
  creamDark: "#e2d3ae",
  green: "#6f9a6b",
  greenDark: "#4d7550",
  blue: "#9cc3dc",
  blueDark: "#6f9bb8",
  wallA: "#b7cdb0",
  wallB: "#9fb897",
  floorA: "#eadcbd",
  floorB: "#e0d0ac",
  metal: "#7c8794",
  metalDark: "#566170",
  screen: "#7fd0e8",
  red: "#d9534f",
  yellow: "#f0c850",
  pot: "#b4684a",
};

export const px = (ctx: Ctx, color: string, x: number, y: number, w = 1, h = 1) => {
  ctx.fillStyle = color;
  ctx.fillRect(x, y, w, h);
};

type Accessory = "glasses" | "headphones" | "cap" | "badge" | "bun";
interface Look { hair: string; skin: string; outfit: string; outfitDark: string; accessory: Accessory }

export const CHARACTER_LOOKS: Record<EmployeeId, Look> = {
  planner: { hair: "#6b3f2a", skin: "#f1c9a5", outfit: "#6f9a6b", outfitDark: "#4d7550", accessory: "glasses" },
  developer: { hair: "#2f2a3a", skin: "#e0ac86", outfit: "#6f9bb8", outfitDark: "#4f7894", accessory: "headphones" },
  qa: { hair: "#c4562d", skin: "#f6d6b8", outfit: "#e0b04a", outfitDark: "#b88a2e", accessory: "cap" },
  security: { hair: "#1f1f24", skin: "#b9805c", outfit: "#4a5568", outfitDark: "#2f3846", accessory: "badge" },
  researcher: { hair: "#e8d9a0", skin: "#f1c9a5", outfit: "#b9825f", outfitDark: "#8a5a34", accessory: "bun" },
};

/** Draws a 12x14 seated character with its top-left at (x, y). `frame` drives the per-state animation. */
export function drawCharacter(ctx: Ctx, id: EmployeeId, x: number, y: number, state: EmployeeState, frame: number) {
  const L = CHARACTER_LOOKS[id];
  const odd = frame % 2 === 1;
  const bob = state === "idle" && frame % 4 >= 2 ? 1 : 0;
  const shake = state === "error" && odd ? 1 : 0;
  const ox = x + shake;
  const oy = y + bob;

  px(ctx, C.ink, ox + 3, oy + 12, 6, 2); // legs/shadow
  px(ctx, L.outfitDark, ox + 4, oy + 12, 4, 1);
  px(ctx, L.outfit, ox + 2, oy + 7, 8, 5); // torso
  px(ctx, L.outfitDark, ox + 2, oy + 11, 8, 1);

  // arms: typing alternates height, completed raises both hands, others rest
  const raised = state === "completed";
  const typing = state === "working";
  const lh = raised ? 3 : typing && odd ? 2 : 4;
  const rh = raised ? 3 : typing && !odd ? 2 : 4;
  px(ctx, L.outfit, ox, oy + 7 + lh - 1 - (raised ? 3 : 0), 2, 5 - lh + 1);
  px(ctx, L.outfit, ox + 10, oy + 7 + rh - 1 - (raised ? 3 : 0), 2, 5 - rh + 1);
  px(ctx, L.skin, ox, oy + (raised ? 5 : 11 - (typing && odd ? 1 : 0)), 2, 1);
  px(ctx, L.skin, ox + 10, oy + (raised ? 5 : 11 - (typing && !odd ? 1 : 0)), 2, 1);

  px(ctx, L.skin, ox + 3, oy + 2, 6, 5); // head
  px(ctx, L.hair, ox + 2, oy, 8, 3);
  px(ctx, L.hair, ox + 2, oy + 3, 1, 3);
  px(ctx, L.hair, ox + 9, oy + 3, 1, 3);
  const blink = state === "idle" && frame % 8 === 7;
  px(ctx, C.ink, ox + 4, oy + (blink ? 5 : 4), 1, blink ? 1 : 2);
  px(ctx, C.ink, ox + 7, oy + (blink ? 5 : 4), 1, blink ? 1 : 2);
  if (state === "error") px(ctx, C.red, ox + 5, oy + 6, 2, 1); // grimace

  switch (L.accessory) {
    case "glasses":
      px(ctx, C.ink, ox + 3, oy + 3, 3, 1);
      px(ctx, C.ink, ox + 6, oy + 3, 3, 1);
      break;
    case "headphones":
      px(ctx, C.ink, ox + 2, oy + 1, 8, 1);
      px(ctx, C.ink, ox + 1, oy + 3, 2, 3);
      px(ctx, C.ink, ox + 9, oy + 3, 2, 3);
      break;
    case "cap":
      px(ctx, C.red, ox + 2, oy, 8, 2);
      px(ctx, C.red, ox + 1, oy + 2, 4, 1);
      break;
    case "badge":
      px(ctx, C.yellow, ox + 7, oy + 8, 2, 2);
      break;
    case "bun":
      px(ctx, L.hair, ox + 4, oy - 2, 4, 2);
      break;
  }
}

/** Small speech bubble above a character, centred on cx. State icon is pixel-drawn. */
export function drawMarker(ctx: Ctx, state: EmployeeState, cx: number, bottom: number, frame: number) {
  if (state === "idle") return;
  const bx = cx - 4;
  const by = bottom - 9;
  px(ctx, C.ink, bx, by, 9, 9);
  px(ctx, state === "error" ? C.red : C.cream, bx + 1, by + 1, 7, 7);
  switch (state) {
    case "working":
      px(ctx, C.blueDark, bx + 2, by + 3, 5, 3);
      px(ctx, C.cream, bx + 2 + (frame % 3) * 2, by + 4, 1, 1);
      break;
    case "thinking":
      for (let i = 0; i <= frame % 3; i++) px(ctx, C.ink, bx + 2 + i * 2, by + 4);
      break;
    case "waiting":
      px(ctx, C.ink, bx + 2, by + 2, 5, 5);
      px(ctx, C.cream, bx + 3, by + 3, 3, 3);
      px(ctx, C.ink, bx + 4, by + 3, 1, 2);
      px(ctx, C.ink, bx + 5, by + 4, 1, 1);
      break;
    case "completed":
      for (const [dx, dy] of [[2, 4], [3, 5], [4, 4], [5, 3], [6, 2]]) px(ctx, C.greenDark, bx + dx, by + dy);
      break;
    case "error":
      px(ctx, C.cream, bx + 4, by + 2, 1, 3);
      px(ctx, C.cream, bx + 4, by + 6);
      break;
  }
}

const LAYER: Record<SceneObject["kind"], number> = {
  rug: 0, window: 1, bookshelf: 1, whiteboard: 1, taskBoard: 1,
  desk: 2, meetingTable: 2, serverRack: 2, network: 2, plant: 2, computer: 3, chair: 4,
};
export const layerOf = (o: SceneObject) => LAYER[o.kind];

export function drawObject(ctx: Ctx, o: SceneObject, frame: number) {
  const x = o.x * TILE;
  const y = o.y * TILE;
  const w = o.w * TILE;
  const h = o.h * TILE;
  switch (o.kind) {
    case "rug":
      px(ctx, C.greenDark, x, y, w, h);
      px(ctx, C.green, x + 2, y + 2, w - 4, h - 4);
      px(ctx, C.cream, x + 5, y + 5, w - 10, 1);
      px(ctx, C.cream, x + 5, y + h - 6, w - 10, 1);
      break;
    case "window":
      px(ctx, C.woodDark, x, y + 1, w, h - 1);
      px(ctx, C.blue, x + 2, y + 3, w - 4, h - 7);
      px(ctx, C.woodDark, x + w / 2 - 1, y + 3, 2, h - 7);
      px(ctx, "#ffffff", x + 3, y + 4, 3, 1);
      px(ctx, C.woodLight, x - 1, y + h - 3, w + 2, 3);
      break;
    case "bookshelf": {
      px(ctx, C.woodDark, x, y, w, h);
      const books = [C.red, C.blueDark, C.green, C.yellow, C.cream];
      for (let row = 0; row < 3; row++) {
        const sy = y + 2 + row * 10;
        px(ctx, C.wood, x + 2, sy, w - 4, 8);
        for (let i = 0; i < Math.floor((w - 4) / 3); i++) {
          const bh = 5 + ((i + row) % 3);
          px(ctx, books[(i + row) % books.length], x + 2 + i * 3, sy + 8 - bh, 2, bh);
        }
      }
      break;
    }
    case "whiteboard":
      px(ctx, C.metal, x, y + 2, w, h - 4);
      px(ctx, "#fbf8ee", x + 2, y + 4, w - 4, h - 8);
      px(ctx, C.blueDark, x + 6, y + 8, 22, 1);
      px(ctx, C.red, x + 6, y + 12, 14, 1);
      px(ctx, C.green, x + 6, y + 16, 26, 1);
      px(ctx, C.yellow, x + w - 14, y + 7, 7, 6);
      break;
    case "taskBoard":
      px(ctx, C.woodDark, x, y + 2, w, h - 4);
      px(ctx, "#c79a63", x + 2, y + 4, w - 4, h - 8);
      px(ctx, C.yellow, x + 4, y + 7, 7, 6);
      px(ctx, "#f2a7b6", x + 14, y + 8, 7, 6);
      px(ctx, C.blue, x + 5, y + 16, 7, 6);
      px(ctx, C.green, x + 16, y + 17, 7, 6);
      break;
    case "desk":
      px(ctx, C.woodDark, x, y + h - 5, w, 5);
      px(ctx, C.wood, x, y, w, h - 5);
      px(ctx, C.woodLight, x, y, w, 2);
      px(ctx, C.cream, x + 4, y + 18, 6, 4);
      px(ctx, C.red, x + w - 10, y + 17, 4, 4);
      break;
    case "computer":
      px(ctx, C.metalDark, x + 2, y + 1, 12, 9);
      px(ctx, C.screen, x + 3, y + 2, 10, 6);
      px(ctx, "#ffffff", x + 4, y + 3 + (frame % 3) * 2, 6, 1);
      px(ctx, C.metal, x + 6, y + 10, 4, 2);
      px(ctx, C.creamDark, x + 3, y + 13, 10, 2);
      break;
    case "chair":
      px(ctx, C.metalDark, x + 3, y + 3, 10, 3);
      px(ctx, C.blueDark, x + 3, y + 6, 10, 7);
      px(ctx, C.metal, x + 5, y + 13, 6, 2);
      break;
    case "meetingTable":
      px(ctx, C.woodDark, x, y + h - 5, w, 5);
      px(ctx, C.wood, x, y, w, h - 5);
      px(ctx, C.woodLight, x, y, w, 2);
      px(ctx, C.metal, x + 8, y + 12, 12, 8);
      px(ctx, C.cream, x + 30, y + 14, 8, 6);
      px(ctx, C.red, x + 46, y + 16, 4, 4);
      break;
    case "serverRack": {
      px(ctx, C.metalDark, x, y, w, h);
      for (let k = 0; k < 5; k++) {
        px(ctx, C.metal, x + 2, y + 3 + k * 9, w - 4, 7);
        px(ctx, (frame + k) % 3 === 0 ? C.yellow : "#6fd08c", x + w - 7, y + 5 + k * 9, 2, 2);
      }
      break;
    }
    case "network":
      px(ctx, C.metalDark, x, y + 4, w, 10);
      for (let i = 0; i < 6; i++) px(ctx, "#222831", x + 3 + i * 4, y + 7, 3, 3);
      px(ctx, (frame % 2) ? "#6fd08c" : C.yellow, x + w - 5, y + 11, 2, 2);
      break;
    case "plant":
      px(ctx, C.pot, x + 4, y + 10, 8, 5);
      px(ctx, C.greenDark, x + 3, y + 3, 10, 8);
      px(ctx, C.green, x + 5, y + 1, 6, 8);
      px(ctx, C.green, x + 2, y + 6, 4, 3);
      break;
  }
}

import { EMPLOYEE_IDS } from "../state/types";
import type { EmployeeId, OfficeState } from "../state/types";
import { COLS, OBJECTS, ROWS, SEATS, TILE } from "./layout";
import { CHAR_BOX, SCENE_H, SCENE_W } from "./hit";
import { C, drawCharacter, drawMarker, drawObject, layerOf, px } from "./sprites";

export interface SceneView {
  state: OfficeState;
  theme: "day" | "night";
  frame: number;
  selectedId: EmployeeId | null;
}

const LABEL_MAX = 12;

export function labelFor(text: string, maxChars: number): string {
  return text.length <= maxChars ? text : text.slice(0, maxChars - 1) + "…";
}

function drawLabel(ctx: CanvasRenderingContext2D, text: string, cx: number, y: number, error: boolean) {
  ctx.font = "7px monospace";
  ctx.textBaseline = "top";
  const w = Math.ceil(ctx.measureText(text).width) + 4;
  const x = Math.min(Math.max(Math.round(cx - w / 2), 1), SCENE_W - w - 1);
  px(ctx, C.ink, x, y, w, 10);
  px(ctx, error ? "#f3c4c0" : "#fbf5e3", x + 1, y + 1, w - 2, 8);
  ctx.fillStyle = error ? "#8a1f1a" : C.ink;
  ctx.fillText(text, x + 2, y + 2);
}

function drawRoom(ctx: CanvasRenderingContext2D) {
  for (let ty = 2; ty < ROWS; ty++) {
    for (let tx = 0; tx < COLS; tx++) {
      px(ctx, (tx + ty) % 2 ? C.floorA : C.floorB, tx * TILE, ty * TILE, TILE, TILE);
    }
  }
  px(ctx, C.wallA, 0, 0, SCENE_W, 28);
  px(ctx, C.wallB, 0, 28, SCENE_W, 2);
  px(ctx, C.woodDark, 0, 30, SCENE_W, 2);
}

function drawNight(ctx: CanvasRenderingContext2D) {
  px(ctx, "rgba(18,28,64,0.5)", 0, 0, SCENE_W, SCENE_H);
  ctx.globalCompositeOperation = "screen";
  for (const id of EMPLOYEE_IDS) {
    const cx = SEATS[id].x * TILE + 8;
    const cy = SEATS[id].y * TILE - 20;
    const g = ctx.createRadialGradient(cx, cy, 2, cx, cy, 36);
    g.addColorStop(0, "rgba(255,214,140,0.45)");
    g.addColorStop(1, "rgba(255,214,140,0)");
    ctx.fillStyle = g;
    ctx.fillRect(cx - 36, cy - 36, 72, 72);
  }
  ctx.globalCompositeOperation = "source-over";
}

export function renderScene(ctx: CanvasRenderingContext2D, view: SceneView): void {
  const { state, frame, selectedId, theme } = view;
  ctx.imageSmoothingEnabled = false;
  drawRoom(ctx);

  const layered = [...OBJECTS].sort((a, b) => layerOf(a) - layerOf(b));
  for (const o of layered) drawObject(ctx, o, frame);

  for (const id of EMPLOYEE_IDS) {
    const emp = state.employees[id];
    const bx = SEATS[id].x * TILE;
    const by = SEATS[id].y * TILE;
    const flash = emp.state === "error" && frame % 2 === 1;
    if (flash) px(ctx, "rgba(217,83,79,0.35)", bx, by + CHAR_BOX.dy, CHAR_BOX.w, CHAR_BOX.h);
    drawCharacter(ctx, id, bx + 2, by - 4, emp.state, frame);
    drawMarker(ctx, emp.state, bx + 8, by - 6, frame);

    const task = emp.currentTaskId ? state.tasks.find((t) => t.id === emp.currentTaskId) : undefined;
    const text = task ? task.title : emp.state[0].toUpperCase() + emp.state.slice(1);
    drawLabel(ctx, labelFor(text, LABEL_MAX), bx + 8, by + 12, emp.state === "error");

    if (selectedId === id) {
      ctx.strokeStyle = "#ffd23f";
      ctx.lineWidth = 1;
      ctx.setLineDash([2, 2]);
      ctx.strokeRect(bx + 0.5, by + CHAR_BOX.dy + 0.5, CHAR_BOX.w - 1, CHAR_BOX.h - 1);
      ctx.setLineDash([]);
    }
  }

  if (theme === "night") drawNight(ctx);
}

import { useEffect, useRef, useState } from "react";
import type { MouseEvent } from "react";
import type { EmployeeId, OfficeState } from "../state/types";
import { SCENE_H, SCENE_W, fitScale, hitTestCharacter } from "./hit";
import { renderScene } from "./renderer";

interface Props {
  state: OfficeState;
  selectedId: EmployeeId | null;
  paused: boolean;
  onSelect: (id: EmployeeId | null) => void;
}

const FRAME_MS = 250;

function useMedia(query: string): boolean {
  const [match, setMatch] = useState(() => window.matchMedia(query).matches);
  useEffect(() => {
    const mq = window.matchMedia(query);
    const on = () => setMatch(mq.matches);
    mq.addEventListener("change", on);
    return () => mq.removeEventListener("change", on);
  }, [query]);
  return match;
}

export default function OfficeCanvas({ state, selectedId, paused, onSelect }: Props) {
  const wrapRef = useRef<HTMLDivElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const frameRef = useRef(0);
  const viewRef = useRef({ state, selectedId });
  viewRef.current = { state, selectedId };
  const [scale, setScale] = useState(1);
  const [hidden, setHidden] = useState(document.hidden);
  const reduced = useMedia("(prefers-reduced-motion: reduce)");
  const animate = !paused && !hidden && !reduced;
  const theme = state.settings.theme;

  const draw = (frame: number) => {
    const ctx = canvasRef.current?.getContext("2d");
    if (ctx) renderScene(ctx, { ...viewRef.current, theme, frame });
  };

  useEffect(() => {
    const el = wrapRef.current;
    if (!el) return;
    const measure = () => setScale(fitScale(el.clientWidth, el.clientHeight));
    measure();
    const ro = new ResizeObserver(measure);
    ro.observe(el);
    return () => ro.disconnect();
  }, []);

  useEffect(() => {
    const on = () => setHidden(document.hidden);
    document.addEventListener("visibilitychange", on);
    return () => document.removeEventListener("visibilitychange", on);
  }, []);

  // Redraw whenever the model changes; reduced motion always shows frame 0.
  useEffect(() => {
    draw(reduced ? 0 : frameRef.current);
  }, [state, selectedId, theme, reduced, scale]);

  useEffect(() => {
    if (!animate) return;
    let raf = 0;
    const tick = (t: number) => {
      const f = Math.floor(t / FRAME_MS);
      if (f !== frameRef.current) {
        frameRef.current = f;
        draw(f);
      }
      raf = requestAnimationFrame(tick);
    };
    raf = requestAnimationFrame(tick);
    return () => cancelAnimationFrame(raf);
  }, [animate, theme]);

  const onClick = (e: MouseEvent<HTMLCanvasElement>) => {
    const r = e.currentTarget.getBoundingClientRect();
    const x = ((e.clientX - r.left) * SCENE_W) / r.width;
    const y = ((e.clientY - r.top) * SCENE_H) / r.height;
    onSelect(hitTestCharacter(x, y));
  };

  return (
    <div className="stage" ref={wrapRef}>
      <canvas
        ref={canvasRef}
        width={SCENE_W}
        height={SCENE_H}
        style={{ width: SCENE_W * scale, height: SCENE_H * scale }}
        onClick={onClick}
        role="img"
        aria-label="Pixel-art office with five employees. Use the employee list to inspect them."
      />
    </div>
  );
}

import { useEffect, useReducer, useState } from "react";
import OfficeCanvas from "./scene/OfficeCanvas";
import { loadState, saveState } from "./state/persistence";
import { reduce } from "./state/reducer";
import type { EmployeeId } from "./state/types";

export default function App() {
  const [state, dispatch] = useReducer(reduce, undefined, loadState);
  const [selectedId, setSelectedId] = useState<EmployeeId | null>(null);
  const [paused, setPaused] = useState(false);

  useEffect(() => saveState(state), [state]);
  useEffect(() => {
    document.documentElement.dataset.theme = state.settings.theme;
  }, [state.settings.theme]);

  return (
    <div className="app">
      <header className="toolbar">
        <h1>Virtual Office</h1>
        <button onClick={() => setPaused((p) => !p)}>{paused ? "Resume" : "Pause"}</button>
      </header>
      <OfficeCanvas state={state} selectedId={selectedId} paused={paused} onSelect={setSelectedId} />
    </div>
  );
}

:root {
  --bg: #e9dfc6;
  --panel: #f6efdc;
  --ink: #3b2c22;
  --edge: #8a5a34;
  --accent: #6f9a6b;
  --accent-ink: #ffffff;
  --danger: #d9534f;
}
:root[data-theme="night"] {
  --bg: #1d2438;
  --panel: #2a3350;
  --ink: #f1e8d0;
  --edge: #b9824f;
  --accent: #6f9bb8;
  --accent-ink: #10192b;
}

* { box-sizing: border-box; }
body {
  margin: 0;
  background: var(--bg);
  color: var(--ink);
  font-family: ui-monospace, "Cascadia Mono", Consolas, monospace;
}

.app { display: flex; flex-direction: column; height: 100vh; }
.toolbar {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 8px 16px;
  background: var(--panel);
  border-bottom: 4px solid var(--edge);
}
.toolbar h1 { font-size: 1rem; margin: 0 auto 0 0; }

.stage {
  flex: 1;
  min-height: 0;
  min-width: 0;
  display: grid;
  place-items: center;
  padding: 16px;
}
.stage canvas {
  image-rendering: pixelated;
  border: 4px solid var(--edge);
  cursor: pointer;
  max-width: 100%;
}

button, select, input {
  font: inherit;
  color: var(--ink);
  background: var(--panel);
  border: 2px solid var(--edge);
  padding: 4px 10px;
  cursor: pointer;
}
button:hover:not(:disabled) { background: var(--accent); color: var(--accent-ink); }
button:disabled { opacity: 0.45; cursor: not-allowed; }
